solution:
// Return a shortest edit script that turns string a into string b.
// Strings are sequences of characters (code points, as `chars` returns them).
// The script is a list of operations applied left to right, one string per
// operation:
//   "=x"   keep character x (the current characters of a and b are both x)
//   "x>y"  substitute character x of a by character y of b (x != y)
//   "-x"   delete character x of a
//   "+y"   insert character y of b
// Every operation except a keep costs 1, and the script must have the
// minimum total cost (the Levenshtein distance between a and b). Keeps
// consume one character of each string, substitutions too, deletes one
// character of a, inserts one character of b, so the script consumes both
// strings completely and in order.
// When several minimum-cost scripts exist, return the one whose sequence of
// operation kinds is lexicographically smallest under the order
// keep < substitute < delete < insert, comparing from the first operation.
// Equal strings give all keeps; both empty gives [].
// Examples:
//   edit_script("kitten", "sitting") == ["k>s", "=i", "=t", "=t", "e>i", "=n", "+g"]
//   edit_script("ab", "ba") == ["a>b", "b>a"]
fn edit_script(a: Str, b: Str) -> List[Str] {
  let xs = chars(a);
  let ys = chars(b);
  let d = suffix_distances(xs, ys);
  let n = len(xs);
  let m = len(ys);
  let mut out = [];
  let mut i = 0;
  let mut j = 0;
  while i < n || j < m {
    if i < n && j < m && xs[i] == ys[j] {
      out = push(out, "=" ++ xs[i]);
      i = i + 1;
      j = j + 1;
    } else if i < n && j < m && d[i][j] == 1 + d[i + 1][j + 1] {
      out = push(out, xs[i] ++ ">" ++ ys[j]);
      i = i + 1;
      j = j + 1;
    } else if i < n && d[i][j] == 1 + d[i + 1][j] {
      out = push(out, "-" ++ xs[i]);
      i = i + 1;
    } else {
      out = push(out, "+" ++ ys[j]);
      j = j + 1;
    }
  }
  out
}

// d[i][j]: edit distance between the suffixes of xs from i and of ys from j.
fn suffix_distances(xs: List[Str], ys: List[Str]) -> List[List[Int]] {
  let n = len(xs);
  let m = len(ys);
  let mut rows_rev: List[List[Int]] = [];
  let mut below: List[Int] = [];
  let mut i = n;
  while i >= 0 {
    // the row is built from j = m down to 0, then reversed
    let mut row_rev: List[Int] = [];
    let mut j = m;
    while j >= 0 {
      let v = if i == n {
        m - j
      } else if j == m {
        n - i
      } else if xs[i] == ys[j] {
        below[j + 1]
      } else {
        1 + min(below[j + 1], min(below[j], row_rev[len(row_rev) - 1]))
      };
      row_rev = push(row_rev, v);
      j = j - 1;
    }
    below = reverse(row_rev);
    rows_rev = push(rows_rev, below);
    i = i - 1;
  }
  reverse(rows_rev)
}
